const webhookData = $input.first().json.body || $input.first().json;
const rawCandidates = webhookData.shortlisted_candidates || webhookData.oa_scores_shortlisted_candidates || [];
const workspaceEmail = 'workspace3705@gmail.com';

const normalizeEmail = (candidate) => String(candidate?.candidate_email || candidate?.email || '').trim().toLowerCase();
const normalizeName = (candidate) => String(candidate?.candidate_name || candidate?.name || candidate?.full_name || '').trim();

const seen = new Set();
return rawCandidates
  .filter((candidate) => {
    const email = normalizeEmail(candidate);
    if (!email) return false;
    if (email === workspaceEmail.toLowerCase()) return false;
    if (seen.has(email)) return false;
    seen.add(email);
    return true;
  })
  .map((candidate) => {
    const rawScore = candidate.resume_score ?? candidate.ai_score ?? candidate.score ?? 0;
    const resumeScore = Number(rawScore) || 0;
    return {
      json: {
        ...candidate,
        candidate_email: normalizeEmail(candidate),
        candidate_name: normalizeName(candidate) || 'Candidate',
        ai_score: resumeScore,
        resume_score: resumeScore,
        _source: 'webhook'
      }
    };
  });

