const staticData = $getWorkflowStaticData('global');
const candidate = $input.first().json || {};
const candidateEmail = String(candidate.candidate_email || candidate.email || '').trim().toLowerCase();

if (!candidateEmail ||
    candidateEmail === 'workspace3705@gmail.com' ||
    !candidateEmail.includes('@') ||
    candidateEmail.length < 5) {
  // Pass through without overwriting staticData
  return [{ json: staticData.currentCandidate ? { ...staticData.currentCandidate } : { skipped: true, reason: 'No valid candidate email' } }];
}

const inferredName = candidateEmail
  ? candidateEmail.split('@')[0].replace(/[._-]+/g, ' ').replace(/\s+/g, ' ').trim().replace(/\b\w/g, (c) => c.toUpperCase())
  : '';
const rawName = String(candidate.candidate_name || candidate.name || candidate.full_name || '').trim();
const normalizedCandidate = {
  ...candidate,
  candidate_email: candidateEmail,
  candidate_name: rawName && rawName.toLowerCase() !== 'candidate' && rawName.toLowerCase() !== 'hr team' ? rawName : inferredName || 'Candidate',
};

staticData.currentCandidate = normalizedCandidate;
return [{ json: normalizedCandidate }];

const workspaceEmail = 'workspace3705@gmail.com';
const staticData = $getWorkflowStaticData('global');

const isValid = (r) => {
  const e = String(r?.candidate_email || r?.email || '').trim().toLowerCase();
  return e.length >= 5 && e.includes('@') && e !== workspaceEmail.toLowerCase();
};

const toTitle = (s) => String(s || '').replace(/[._-]+/g, ' ').replace(/\s+/g, ' ').trim().replace(/\b\w/g, (c) => c.toUpperCase());

const inputRows = ($input.all() || []).map((i) => i.json || {});

// PRIORITY 1: staticData set by Store Candidate — most reliable
let candidate = (staticData.currentCandidate && isValid(staticData.currentCandidate))
  ? staticData.currentCandidate
  : null;

// PRIORITY 2: any valid row in input (not calendar events)
if (!candidate) {
  candidate = inputRows.find((r) => isValid(r)) || null;
}

if (!candidate || !isValid(candidate)) {
  return [{ json: { skipped: true, reason: 'Invalid or missing candidate context' } }];
}

// Persist back in case it was resolved from input
staticData.currentCandidate = candidate;

const busyEvents = inputRows.filter((evt) => {
  const s = evt?.start?.dateTime || evt?.start?.date;
  const e = evt?.end?.dateTime || evt?.end?.date;
  return Boolean(s && e);
});

const candidateEmail = String(candidate.candidate_email || candidate.email || '').trim().toLowerCase();
const inferredName = candidateEmail ? toTitle(candidateEmail.split('@')[0]) : '';
const rawCandidateName = String(candidate.candidate_name || candidate.name || candidate.full_name || '').trim();
const candidateName = rawCandidateName && !/^(candidate|undefined|null|hr team)$/i.test(rawCandidateName) ? rawCandidateName : (inferredName || 'Unknown');
const resumeScore = Number(candidate.resume_score ?? candidate.ai_score ?? 0) || 0;
const interviewer = { id: 1, name: 'HR Team', email: workspaceEmail };

const IST_OFFSET = 5.5 * 60 * 60 * 1000;
let interviewTime = new Date(Date.now() + IST_OFFSET);
interviewTime.setUTCDate(interviewTime.getUTCDate() + 1);
interviewTime.setUTCHours(4, 0, 0, 0); // 09:30 IST workday anchor

let found = false;
let attempts = 0;
while (!found && attempts < 240) {
  attempts++;
  const istDay = new Date(interviewTime.getTime() + IST_OFFSET).getUTCDay();
  if (istDay === 0 || istDay === 6) {
    interviewTime.setUTCDate(interviewTime.getUTCDate() + 1);
    interviewTime.setUTCHours(4, 0, 0, 0);
    continue;
  }

  const slotStart = interviewTime.getTime();
  const slotEnd = slotStart + 2700000;
  const conflict = busyEvents.some((evt) => {
    const start = new Date(evt?.start?.dateTime || evt?.start?.date).getTime();
    const end = new Date(evt?.end?.dateTime || evt?.end?.date).getTime();
    if (!Number.isFinite(start) || !Number.isFinite(end)) return false;
    return slotStart < end && slotEnd > start;
  });

  if (!conflict) {
    found = true;
  } else {
    interviewTime = new Date(interviewTime.getTime() + 60 * 60 * 1000);
    const istHour = new Date(interviewTime.getTime() + IST_OFFSET).getUTCHours();
    if (istHour >= 17) {
      interviewTime.setUTCDate(interviewTime.getUTCDate() + 1);
      interviewTime.setUTCHours(4, 0, 0, 0);
    }
  }
}

if (!found) {
  interviewTime.setUTCDate(interviewTime.getUTCDate() + 1);
  interviewTime.setUTCHours(4, 0, 0, 0);
  while (true) {
    const istDay = new Date(interviewTime.getTime() + IST_OFFSET).getUTCDay();
    if (istDay !== 0 && istDay !== 6) break;
    interviewTime.setUTCDate(interviewTime.getUTCDate() + 1);
    interviewTime.setUTCHours(4, 0, 0, 0);
  }
}

const endTime = new Date(interviewTime.getTime() + 2700000);

return [{
  json: {
    ...candidate,
    skipped: false,
    candidate_email: candidateEmail,
    candidate_name: candidateName,
    ai_score: resumeScore,
    resume_score: resumeScore,
    round_number: 1,
    round_label: 'HR Round',
    interview_format: 'video call',
    interviewerId: interviewer.id,
    interviewerName: interviewer.name,
    interviewerEmail: interviewer.email,
    interviewer_count: 1,
    scheduling_warning: found ? null : 'Fallback slot assigned.',
    calendar_warning: busyEvents.length ? null : 'No calendar data; slot chosen without conflict check.',
    meetingTitle: `Interview with ${candidateName} (HR Round)`,
    audit_start: interviewTime.toISOString(),
    audit_end: endTime.toISOString()
  }
}];

